@router.get("/api/cards/{card_id}/signoff/open")
def open_in_app(card_id: str):
    """
    The sign-off page for someone signed in to the app: a valid link to the newest unanswered
    request of the case, without sending anything (the push went out when it was passed on).
    """
    api = _api()
    req = latest_for(card_id)
    if req is None or req.get("answer"):
        raise HTTPException(409, "Nothing is waiting on anyone here.")
    cur = api.now()
    with _lock:
        tokens = {
            k: v for k, v in _tokens().items() if (api.parse_ts(v.get("expires_at")) or cur) > cur
        }
        token = next((k for k, v in tokens.items() if v.get("request") == req["id"]), None)
        if token is None:
            token = secrets.token_urlsafe(18)
            tokens[token] = {
                "request": req["id"],
                "created_at": cur.isoformat(),
                "expires_at": _expires().isoformat(),
            }
            api.write_json(TOKENS, tokens)
    return {"path": f"/ok/{token}"}


@router.post("/api/cards/{card_id}/signoff/resend")
def resend(card_id: str):
    """Send the newest request of a case again (fresh link); for an escalation passed on before
    links existed, create its request first."""
    api = _api()
    card = api._card(card_id)
    req = latest_for(card_id)
    if req and req.get("answer"):
        raise HTTPException(409, "This was answered already.")
    if req is None:
        if card["status"] != "escalated":
            raise HTTPException(409, "Nothing is waiting on anyone here.")
        act = next(
            (
                a
                for a in reversed(api.read_list("actions.json"))
                if a.get("decision_id") == card_id and a.get("kind") == "escalate"
            ),
            {},
        )
        out = escalation(
            card,
            act.get("option"),
            str(act.get("note") or ""),
            api.viewer_name(api.portal_root()),
            act.get("at"),
        )
        if out is None:
            raise HTTPException(409, "There is nobody named to approve this.")
        start_simulation(out["request"])
        return out
    out = send(req["id"])
    if req["kind"] == "escalation":
        start_simulation(req["id"])
    return out
// Who uses this device: the buyer (lands on Today) or the approver who signs money (lands on
// Launch). Remembered per device; no choice means Today. Names come from /api/state.

export type Role = 'buyer' | 'approver'

const KEY = 'ask-soony.as'

export function savedRole(): Role | null {
  try {
    const v = window.localStorage.getItem(KEY)
    return v === 'buyer' || v === 'approver' ? v : null
  } catch {
    return null
  }
}

export function saveRole(r: Role | null) {
  try {
    if (r) window.localStorage.setItem(KEY, r)
    else window.localStorage.removeItem(KEY)
  } catch { /* private mode: the choice lasts this visit */ }
}

/** First name as people say it: 'Dr. Maren Vogt, Head of Procurement' -> 'Maren'. */
export const firstNameOf = (s?: string | null) => (s ?? '').split(',')[0].split(' ').find((w) => w && !w.endsWith('.')) || ''

/** ?as=<first name | buyer | approver>: the role it names, or null when it names nobody. */
export function roleFromParam(v: string | null, names: { viewer?: string | null; approver?: string | null }): Role | null {
  const x = (v ?? '').trim().toLowerCase()
  if (!x) return null
  if (x === 'buyer' || x === 'approver') return x
  if (names.approver && firstNameOf(names.approver).toLowerCase() === x) return 'approver'
  if (names.viewer && firstNameOf(names.viewer).toLowerCase() === x) return 'buyer'
  return null
}

/**
 * What reaches the person who signs: cases that are red for the launch, that she signs, or that
 * cost money. Everything else stays with the buyer, who sees every case.
 */
export function mattersToApprover(
  c: { id: string; level?: string; signoff?: string | null; approver?: string | null },
  approver: string | null | undefined,
  priced: Set<string>,
): boolean {
  if (c.level === 'red' || priced.has(c.id)) return true
  const me = firstNameOf(approver)
  return !!me && (firstNameOf(c.signoff) === me || firstNameOf(c.approver) === me)
}

/** 'Dr. Maren Vogt, Head of Procurement' -> 'Head of Procurement'; no title given: the role's name. */
export function roleTitle(role: Role, label?: string | null): string {
  const t = (label ?? '').split(',').slice(1).join(',').trim()
  return t || (role === 'buyer' ? 'Buyer' : 'Approver')
}
import { fmtTime, post, type Card, type SignoffRequest } from '@/lib/api'
import { when } from '@/lib/decisions'

// Where a passed-on case or an internal message went, and what came back, in one honest line:
// "Sent to Maren's phone at 07:49", "Not delivered: no channel reaches Maren", "Maren approved at
// 08:12", "Maren declined: too expensive". Read from card.signoff_request (signoff.py).

const possessive = (who: string) => (who.endsWith('s') ? `${who}'` : `${who}'s`)

/** Where it went: "Maren's phone", "Teams", "Maren's phone and Teams". */
export function reachedWhere(r: Pick<SignoffRequest, 'who' | 'channels'>): string {
  const bits = [r.channels.includes('push') ? `${possessive(r.who)} phone` : '', r.channels.includes('teams') ? 'Teams' : '']
  return bits.filter(Boolean).join(' and ')
}

export function signoffLine(card: Card, nowMs: number): string | null {
  const r = card.signoff_request
  if (!r) return null
  const a = r.answer
  if (a?.decision === 'approved') return `${r.who} approved at ${when(a.at, nowMs)}${a.simulated ? ' (simulated for the demo)' : ''}`
  if (a?.decision === 'declined') return `${r.who} declined${a.note ? `: ${a.note}` : ''}`
  if (a?.decision === 'done') return `${r.who}: done at ${when(a.at, nowMs)}`
  const ack = r.acks[r.acks.length - 1]
  if (ack?.answer === 'got_it') return `${r.who} got it at ${when(ack.at, nowMs)}`
  if (!r.delivered) return `Not delivered: no channel reaches ${r.who}`
  return `Sent to ${reachedWhere(r)} at ${when(r.sent_at, nowMs)}`
}

/** True while a request waits for its person (Send again makes sense). */
export const signoffOpen = (card: Card) => !!card.signoff_request && !card.signoff_request.answer

/** The done screen after Pass it on or an internal message: where it really went. */
export function sentSub(who: string, channels: string[] | undefined, nowIso = new Date().toISOString()): string {
  if (!channels) return 'Recorded.'
  if (!channels.length) return `Not delivered: no channel reaches ${who}. Recorded only; tell them yourself.`
  return `Sent to ${reachedWhere({ who, channels: channels as SignoffRequest['channels'] })} at ${fmtTime(nowIso)}. You'll see their answer here.`
}

export const resendSignoff = (cardId: string) =>
  post<{ channels: string[]; at: string }>(`/api/cards/${encodeURIComponent(cardId)}/signoff/resend`)

