U=$(grep '^ASK_APP_URL=' .env | tail -1 | cut -d= -f2- | tr -d '"'); P=$(grep '^ASK_DASHBOARD_PASSWORD=' .env | tail -1 | cut -d= -f2- | tr -d '"'); curl -s -m 20 -u "x:$P" "$U/api/state" -o $CLAUDE_JOB_DIR/tmp/live.json -w '%{http_code}\n'; python3 -I - $CLAUDE_JOB_DIR/tmp/live.json <<'EOF'
import json,sys
s=json.load(open(sys.argv[1])); m=(s.get("launch") or {}).get("money") or {}
print("approver:",m.get("approver"))
for c in s["cards"]:
    r=c.get("signoff_request")
    if c["status"]=="escalated" or r:
        print(c["id"][:45],c["status"],"| approver:",c.get("approver"),"| req:",r and {k:r[k] for k in ("kind","who","channels","delivered","answer","sent_at")})
EOF

